use super::*;

/// Which GRAMMAR's node kinds a walk should compare against.
///
/// A tree-sitter walk is a string comparison against node kinds, and the two grammars spell everything
/// differently — `function_item` against `function_declaration`, a `visibility_modifier` child against
/// an `export_statement` parent. The LANGUAGE alone cannot carry that: TypeScript has two languages
/// (`.ts` and `.tsx`) and ONE set of node kinds, so a walk that branched on the `Language` would have
/// to branch twice for one decision.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum Grammar {
    Rust,
    TypeScript,
}

/// The grammar + tree-sitter language a record's `code` should be parsed with.
///
/// TAKES THE RECORD'S `src`, NOT ONLY ITS `tech`, and that argument is the whole reason TypeScript can
/// be classified at all. `tech` is `"typescript"` for BOTH dialects, so it cannot pick a grammar — the
/// extension is the only thing that can, and it lives on `src`.
///
/// **TSX IS NOT A STRICT SUPERSET OF TS**, whatever the folklore (and `bsc-ui`'s `harvest`, which
/// parses every TypeScript file as TSX and says so in a comment). The two grammars disagree in both
/// directions and each direction is a silent mis-parse, never an error the caller sees:
///
/// ```text
/// let n = <number>y;      parses clean as TS   ·  ERRORS as TSX (an unclosed JSX element)
/// const el = <Foo />;     ERRORS as TS         ·  parses clean as TSX
/// ```
///
/// MEASURED over the 706 TypeScript records: the corpus happens to survive an all-TSX parse — no
/// non-`.tsx` record uses the angle-bracket type-assertion form, and all 14 dialect disagreements are
/// `.tsx` records where plain TS fails — but that is a property of today's corpus that nothing guards,
/// and a mis-parsed module silently yields ZERO leaves rather than an error. So the extension picks the
/// dialect, as `bsc-graph--extract--mod.rs` already does for the file walk.
///
/// Anything that is not `.tsx` reads as plain TypeScript, INCLUDING a record with no `src` at all: a
/// record whose module has no file here is still ordinary TypeScript, and refusing it would make the
/// classifier's population depend on a field that is optional by design (`impl set --no-src`).
pub(crate) fn language_for(tech: &str, src: &str) -> Option<(Grammar, tree_sitter::Language)> {
    match tech {
        "rust" => Some((Grammar::Rust, tree_sitter_rust::LANGUAGE.into())),
        "typescript" => Some(if src.ends_with(".tsx") {
            (Grammar::TypeScript, tree_sitter_typescript::LANGUAGE_TSX.into())
        } else {
            (Grammar::TypeScript, tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into())
        }),
        _ => None,
    }
}
